$tests=0;$failures=0;
function bh_assert($v,$message='Assertion failed'){if(!$v)throw new RuntimeException($message);}
function bh_case($name,$fn){global $tests,$failures;$tests++;try{$fn();echo 'PASS '.$name."\n";}catch(Throwable $e){$failures++;echo 'FAIL '.$name.': '.$e->getMessage()."\n";}}
function bh_reject($fn,$code){try{$fn();}catch(Throwable $e){bh_assert(strpos($e->getMessage(),$code)!==false,'Wrong error '.$e->getMessage());return;}throw new RuntimeException('Expected '.$code);}
function bh_fixture($n){$p=glob(__DIR__.'/study-engine/fixtures/valid/'.$n.'*.json');return json_decode(file_get_contents($p[0]),true);}
bh_case('Builder cold load catalogs native randomizations without Assessment runtime',function(){
    bh_assert(!class_exists('EIPSI\\AssessmentEditor\\Runtime\\Owner',false));
    require_once __DIR__.'/../includes/study-engine/builder/Service.php';
    $method=new ReflectionMethod(B\Service::class,'nativeRandomizations');$method->setAccessible(true);
    $child=array('id'=>'Q_ONE','type'=>'text','children'=>array(),'randomization'=>array('weight'=>3,'always_show'=>false,'fixed_position'=>true));
    $element=array('id'=>'R_ONE','type'=>'randomization','properties'=>array('label'=>'Random','mode'=>'all','count'=>1),'children'=>array($child));
    $catalog=$method->invoke(null,array('elements'=>array($element)));
    bh_assert(count($catalog)===1&&$catalog[0]['weights']['Q_ONE']===3&&$catalog[0]['fixed']===array('Q_ONE'));
    $child['randomization']['weight']=0;$element['children']=array($child);
    bh_reject(function()use($method,$element){$method->invoke(null,array('elements'=>array($element)));},'Peso debe ser positivo');
    bh_assert(!class_exists('EIPSI\\AssessmentEditor\\Runtime\\Owner',false));
});
