function bh_product($type='LONGITUDINAL'){
    $d=B\Draft::create('STUDY_PRODUCT','PUBLIC_PRODUCT');$d['protocol_metadata']['study_type']=$type;$d['timezone']['policy']='PARTICIPANT_LOCAL';$d['nodes'][0]['children_strategy']='PARALLEL_AVAILABLE';$d['nodes'][0]['metadata']['independent_children']=true;
    if($type==='LONGITUDINAL'){$d=EIPSI\StudyEngine\Longitudinal\Configuration::apply($d,array('reminder_offsets'=>array()));$block=B\Draft::block('L1',$d['id'],'M_ROOT','MACRO',0);$block['children_strategy']='PARALLEL_AVAILABLE';$block['metadata']=array('role'=>'LONGITUDINAL_BLOCK','independent_children'=>true);$d['nodes'][]=$block;}
    foreach(array('E1','E2') as $index=>$id){if($type==='TRANSVERSAL'&&$index===1)break;$n=B\Draft::block($id,$d['id'],$type==='LONGITUDINAL'?'L1':'M_ROOT','MICRO',$index);$n['metadata']['native_version_id']='NV_TEST';$n['metadata']['native_definition_hash']=str_repeat('a',64);$n['schedule']=B\Draft::schedule();$n['schedule']['timezone_policy']='PARTICIPANT_LOCAL';if($type==='LONGITUDINAL'){$n['schedule']['temporal_rule']=array('kind'=>'LOCAL_DAY_TIME','day_index'=>1,'time'=>'09:00');$n['schedule']['window']=array('kind'=>'DURATION','duration'=>array('kind'=>'ELAPSED','seconds'=>7200));$n['metadata']['scheduled_interaction']=array('delivery'=>'RANDOM','window_seconds'=>3600,'reminders'=>array(1800,3600));}$d['nodes'][]=$n;$json=C\Canonical::json(array('label'=>'Example','html'=>''));$d['nodes'][]=array('kind'=>'CONTENT','id'=>'C_'.$id,'version_id'=>$d['id'],'parent_id'=>$id,'position'=>0,'type'=>'TEXT','content'=>array('content_id'=>'CC_'.$id,'version'=>1,'snapshot'=>$json,'sha256'=>hash('sha256',$json)),'durable_reference'=>null);}
    return $d;
}
function bh_product_sim($d){return new E\Simulator((new E\DefinitionCompiler())->compile($d),array('execution_id'=>'PRODUCT_EXEC','created_at'=>'2026-10-12T08:00:00Z','timezone'=>'UTC','seed_hex'=>str_repeat('01',32)));}
