bh_case('Product overlapping opportunities remain independently available',function(){$d=bh_product();foreach($d['nodes'] as &$n)if(isset($n['metadata']['scheduled_interaction']))$n['metadata']['scheduled_interaction']['delivery']='START';unset($n);$sim=bh_product_sim($d);$sim->dispatch(array('id'=>'CLOCK','kind'=>'ADVANCE_TIME','data'=>array('at'=>'2026-10-12T09:00:00Z')));bh_assert($sim->instance('E1')['state']==='AVAILABLE'&&$sim->instance('E2')['state']==='AVAILABLE');});
bh_case('Product random delivery is in window and availability starts at delivery',function(){$sim=bh_product_sim(bh_product());$i=$sim->instance('E1');bh_assert($i['available_at']>='2026-10-12T09:00:00Z'&&$i['available_at']<'2026-10-12T10:00:00Z');bh_assert(strtotime($i['due_at'])-strtotime($i['available_at'])===7200);});
