bh_case('Product completion dependency remains unplanned without completion',function(){$d=bh_product();foreach($d['nodes'] as &$n)if($n['id']==='E2'){$n['schedule']['anchor']='SPECIFIC_BLOCK_COMPLETED';$n['schedule']['anchor_ref']='E1';$n['schedule']['occurrence_selector']=array('kind'=>'SINGLE');$n['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'CALENDAR','amount'=>7,'unit'=>'DAY'));}unset($n);$sim=bh_product_sim($d);bh_assert($sim->instance('E2')['available_at']===null);$sim->dispatch(array('id'=>'LATE','kind'=>'ADVANCE_TIME','data'=>array('seconds'=>86400)));bh_assert($sim->instance('E2')['available_at']===null&&$sim->instance('E2')['state']==='NOT_SCHEDULED');});
