bh_case('Product delivery window requires quarter-hour increments',function(){$d=bh_product();foreach($d['nodes'] as &$n)if($n['id']==='E1')$n['metadata']['scheduled_interaction']['window_seconds']=901;unset($n);bh_reject(function()use($d){B\Draft::validate($d);},'INVALID_DELIVERY_WINDOW');});
