bh_case('Product completion dependency cycles rejected',function(){$d=bh_product();foreach($d['nodes'] as &$n)if(in_array($n['id'],array('E1','E2'),true)){$n['schedule']['anchor']='SPECIFIC_BLOCK_COMPLETED';$n['schedule']['anchor_ref']=$n['id']==='E1'?'E2':'E1';$n['schedule']['occurrence_selector']=array('kind'=>'SINGLE');$n['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'CALENDAR','amount'=>7,'unit'=>'DAY'));}unset($n);bh_reject(function()use($d){bh_product_sim($d);},'TEMPORAL_CYCLE');});
bh_case('Product local selection draws exactly one and recovers without rerandomizing',function(){$d=bh_product();$first=null;foreach($d['nodes'] as $n)if($n['id']==='E1')$first=$n;$random=B\Draft::block('LOCAL',$d['id'],'L1','MACRO',0);$random['schedule']=$first['schedule'];$random['metadata']=array('role'=>'LOCAL_RANDOMIZATION','independent_children'=>true,'scheduled_interaction'=>$first['metadata']['scheduled_interaction']);$random['children_strategy']='WEIGHTED_RANDOM';$random['randomization']=array('strategy'=>'WEIGHTED_RANDOM','scope'=>'EXECUTION','candidates'=>array('E1','E2'),'select_n'=>null,'draw_count'=>1,'weights'=>array('E1'=>1,'E2'=>2),'order'=>'DEFINITION','algorithm_version'=>'EIPSI_RANDOM_V1');foreach($d['nodes'] as &$n)if(in_array($n['id'],array('E1','E2'),true)){$n['parent_id']='LOCAL';$n['schedule']=B\Draft::schedule('BLOCK_AVAILABLE','LOCAL');$n['schedule']['window']=$first['schedule']['window'];unset($n['metadata']['scheduled_interaction']);}unset($n);$d['nodes'][]=$random;$sim=bh_product_sim($d);$sim->dispatch(array('id'=>'ACTIVATE','kind'=>'ADVANCE_TIME','data'=>array('at'=>'2026-10-12T10:00:00Z')));$decisions=$sim->snapshot()['random_decisions'];bh_assert(count($decisions)===1);$decision=array_values($decisions)[0];bh_assert(count($decision['selection'])===1);$chosen=$decision['selection'][0];bh_assert($sim->instance($chosen)['state']==='AVAILABLE');$restore=E\Simulator::restore($sim->compiled(),$sim->checkpoint(),str_repeat('01',32));$restore->dispatch(array('id'=>'REFRESH','kind'=>'RELOAD'));bh_assert($restore->snapshot()['random_decisions']===$decisions);});
bh_case('Product block randomization selects N without replacement and keeps authored order',function(){$d=bh_product();$prototype=null;$content=null;foreach($d['nodes'] as $n){if($n['id']==='E1')$prototype=$n;if($n['id']==='C_E1')$content=$n;}foreach(array('L2','L3') as $i=>$id){$block=B\Draft::block($id,$d['id'],'BR','MACRO',$i+1);$block['metadata']=array('role'=>'LONGITUDINAL_BLOCK','independent_children'=>true);$block['children_strategy']='PARALLEL_AVAILABLE';$d['nodes'][]=$block;$assessment=$prototype;$assessment['id']='E'.($i+3);$assessment['logical_id']=$assessment['id'];$assessment['parent_id']=$id;$assessment['position']=0;$d['nodes'][]=$assessment;$c=$content;$c['id']='C_'.$assessment['id'];$c['parent_id']=$assessment['id'];$d['nodes'][]=$c;}foreach($d['nodes'] as &$n)if($n['id']==='L1')$n['parent_id']='BR';unset($n);$r=B\Draft::block('BR',$d['id'],'M_ROOT','MACRO',0);$r['metadata']=array('role'=>'BLOCK_RANDOMIZATION','independent_children'=>true);$r['children_strategy']='WEIGHTED_RANDOM';$r['randomization']=array('strategy'=>'WEIGHTED_RANDOM','scope'=>'EXECUTION','candidates'=>array('L1','L2','L3'),'select_n'=>null,'draw_count'=>2,'weights'=>array('L1'=>1,'L2'=>2,'L3'=>1),'order'=>'DEFINITION','algorithm_version'=>'EIPSI_RANDOM_V1');$d['nodes'][]=$r;$sim=bh_product_sim($d);$decision=array_values($sim->snapshot()['random_decisions'])[0];$chosen=$decision['selection'];bh_assert(count($chosen)===2&&count(array_unique($chosen))===2);$expected=array_values(array_intersect(array('L1','L2','L3'),$chosen));bh_assert($chosen===$expected);$sim->dispatch(array('id'=>'CLOCK','kind'=>'ADVANCE_TIME','data'=>array('at'=>'2026-10-12T10:00:00Z')));foreach($chosen as $id)bh_assert(in_array($sim->instance($id)['state'],array('AVAILABLE','IN_PROGRESS'),true));});
function bh_transversal_selection(){$d=bh_product('TRANSVERSAL');$first=null;$content=null;foreach($d['nodes'] as $n){if($n['id']==='E1')$first=$n;if($n['id']==='C_E1')$content=$n;}$second=$first;$second['id']='E2';$second['logical_id']='E2';$second['position']=1;$d['nodes'][]=$second;$content['id']='C_E2';$content['parent_id']='E2';$d['nodes'][]=$content;foreach($d['nodes'] as &$n)if(in_array($n['id'],array('E1','E2'),true))$n['parent_id']='TRANS_R';unset($n);$r=B\Draft::block('TRANS_R',$d['id'],'M_ROOT','MACRO',0);$r['schedule']=B\Draft::schedule();$r['metadata']=array('role'=>'TRANSVERSAL_RANDOMIZATION','independent_children'=>true);$r['children_strategy']='WEIGHTED_RANDOM';$r['randomization']=array('strategy'=>'WEIGHTED_RANDOM','scope'=>'EXECUTION','candidates'=>array('E1','E2'),'select_n'=>null,'draw_count'=>1,'weights'=>array('E1'=>1,'E2'=>3),'order'=>'DEFINITION','algorithm_version'=>'EIPSI_RANDOM_V1');$d['nodes'][]=$r;return $d;}
bh_case('Transversal selects one Native candidate immediately and restores the assignment',function(){$sim=bh_product_sim(bh_transversal_selection());$s=$sim->snapshot();bh_assert($sim->nextAction()['kind']==='OPEN_ASSESSMENT');$choices=array_values($s['random_decisions']);bh_assert(count($choices)===1&&count($choices[0]['selection'])===1);$restore=E\Simulator::restore($sim->compiled(),$sim->checkpoint(),str_repeat('01',32));bh_assert($restore->snapshot()['random_decisions']===$s['random_decisions']);$restore->dispatch(array('id'=>'DONE_TRANS','kind'=>'SUBMIT_ASSESSMENT','data'=>array('node_id'=>$choices[0]['selection'][0])));bh_assert($restore->snapshot()['execution']['state']==='COMPLETED');});
bh_case('Transversal refuses multiple selections and scheduling',function(){$d=bh_transversal_selection();foreach($d['nodes'] as &$n)if($n['id']==='TRANS_R')$n['randomization']['draw_count']=2;unset($n);bh_assert(in_array('TRANSVERSAL_SELECT_EXACTLY_ONE',array_column(B\Draft::diagnostics($d),'code'),true));$d=bh_transversal_selection();foreach($d['nodes'] as &$n)if($n['id']==='E1')$n['schedule']['temporal_rule']=array('kind'=>'LOCAL_DAY_TIME','day_index'=>2,'time'=>'09:00');unset($n);bh_assert(in_array('TRANSVERSAL_MUST_BE_IMMEDIATE',array_column(B\Draft::diagnostics($d),'code'),true));});
bh_case('Relative verification trigger stays blocked until verification then adds elapsed delay',function(){$d=bh_product();foreach($d['nodes'] as &$n)if($n['id']==='E1'){$n['schedule']['anchor']='PARTICIPANT_VERIFIED';$n['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'ELAPSED','seconds'=>900));$n['metadata']['scheduled_interaction']['timing']='RELATIVE';$n['metadata']['scheduled_interaction']['delivery']='START';}unset($n);$sim=bh_product_sim($d);bh_assert($sim->instance('E1')['available_at']===null);$sim->dispatch(array('id'=>'VERIFY_NEW','kind'=>'VERIFY_PARTICIPANT'));bh_assert($sim->instance('E1')['available_at']==='2026-10-12T08:15:00Z');});
bh_case('Relative study-start schedule uses exact elapsed delay',function(){$d=bh_product();foreach($d['nodes'] as &$n)if($n['id']==='E1'){$n['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'ELAPSED','seconds'=>900));$n['metadata']['scheduled_interaction']['timing']='RELATIVE';$n['metadata']['scheduled_interaction']['delivery']='START';}unset($n);$sim=bh_product_sim($d);bh_assert($sim->instance('E1')['available_at']==='2026-10-12T08:15:00Z');});
bh_case('Mandatory available assessment precedes optional and forbids bypass',function(){$d=bh_product();foreach($d['nodes'] as &$n)if(in_array($n['id'],array('E1','E2'),true)){$n['metadata']['scheduled_interaction']['delivery']='START';if($n['id']==='E2')$n['metadata']['scheduled_interaction']['mandatory']=true;}unset($n);$sim=bh_product_sim($d);$sim->dispatch(array('id'=>'NOW_REQUIRED','kind'=>'ADVANCE_TIME','data'=>array('at'=>'2026-10-12T09:00:00Z')));bh_assert($sim->nextAction()['payload']['assessment_execution_id']===$sim->instance('E2')['id']);bh_reject(function()use($sim){$sim->dispatch(array('id'=>'BYPASS_REQUIRED','kind'=>'SUBMIT_ASSESSMENT','data'=>array('node_id'=>'E1')));},'MANDATORY_ASSESSMENT_REQUIRED');$sim->dispatch(array('id'=>'ANSWER_REQUIRED','kind'=>'SUBMIT_ASSESSMENT','data'=>array('node_id'=>'E2')));bh_assert($sim->nextAction()['payload']['assessment_execution_id']===$sim->instance('E1')['id']);});
bh_case('Interaction flags reject non-boolean values',function(){$d=bh_product();foreach($d['nodes'] as &$n)if($n['id']==='E1')$n['metadata']['scheduled_interaction']['mandatory']='yes';unset($n);bh_reject(function()use($d){B\Draft::validate($d);},'INVALID_BOOLEAN');});
echo $tests.' tests, '.$failures." failures\n";exit($failures?1:0);
